// tmdbApi.js
import axios from "axios";

const TMDB_API_KEY = "YOUR_TMDB_API_KEY"; // ← 발급받은 키로 교체
const BASE_URL = "https://api.themoviedb.org/3";

/**
 * 영화 제목과 연도를 기반으로 포스터 이미지 URL 반환
 * @param {string} title - 영화 제목 (예: "인생은 아름다워")
 * @param {string} year - 개봉 연도 (예: "1997")
 * @returns {string|null} - 이미지 URL 또는 null
 */
export const getPosterFromTMDB = async (title, year) => {
  try {
    const response = await axios.get(`${BASE_URL}/search/movie`, {
      params: {
        api_key: TMDB_API_KEY,
        query: title,
        language: "ko-KR",
        primary_release_year: year,
        // region: "KR", // 제거 권장
      },
    });

    const results = response.data.results;
    if (!results || results.length === 0) {
      console.warn("TMDB 검색 결과 없음");
      return null;
    }

    const movie = results[0]; // 가장 첫 결과 사용

    if (movie.poster_path) {
      return `https://image.tmdb.org/t/p/w780${movie.poster_path}`;
    } else if (movie.backdrop_path) {
      return `https://image.tmdb.org/t/p/w780${movie.backdrop_path}`;
    } else {
      return null; // 이미지 없음
    }
  } catch (error) {
    console.error("TMDB 포스터 불러오기 실패:", error);
    return null;
  }
};
